(function(){
  "use strict";
  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  /* ============ 1. REVEAL ON SCROLL ============ */
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(e.isIntersecting){ e.target.classList.add("in"); io.unobserve(e.target); }
    });
  }, { threshold: 0.12 });
  document.querySelectorAll(".rv").forEach(function(el){ io.observe(el); });

  /* ============ 2. THE PARTICLE PERSON ============ */
  var canvas = document.getElementById("person");
  var ctx = canvas.getContext("2d");
  var W = 0, H = 0, DPR = Math.min(window.devicePixelRatio || 1, 1.5);

  function ellipse(x, cx, cy, rx, ry, fill){
    x.beginPath(); x.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2); x.fillStyle = fill; x.fill();
  }
  function poly(x, pts, fill){
    x.beginPath(); x.moveTo(pts[0], pts[1]);
    for(var i = 2; i < pts.length; i += 2) x.lineTo(pts[i], pts[i + 1]);
    x.closePath(); x.fillStyle = fill; x.fill();
  }
  function vgrad(x, y0, y1, stops){
    var g = x.createLinearGradient(0, y0, 0, y1);
    stops.forEach(function(s){ g.addColorStop(s[0], s[1]); });
    return g;
  }

  /* Draw the silhouette once, off-screen (440 x 1080 figure space).
     Brightness in the drawing becomes brightness of the dots. */
  function drawFigure(x){
    var body = vgrad(x, 200, 600, [[0,"#e8e8e8"],[1,"#8a8a8a"]]);
    var cloth = vgrad(x, 540, 960, [[0,"#c9c9c9"],[1,"#6f6f6f"]]);
    /* hood */
    ellipse(x, 220, 158, 110, 130, vgrad(x, 30, 290, [[0,"#f2f2f2"],[1,"#9a9a9a"]]));
    /* face — kept dark, like the shadowed face in the reference */
    ellipse(x, 220, 152, 67, 82, "#484848");
    ellipse(x, 220, 128, 40, 30, "#5c5c5c");
    /* torso / jacket */
    poly(x, [126,252, 314,252, 340,575, 100,575], body);
    /* arms */
    poly(x, [130,262, 88,306, 82,548, 126,566], cloth);
    poly(x, [310,262, 352,306, 358,548, 314,566], cloth);
    /* legs */
    poly(x, [146,572, 215,572, 209,928, 140,928], cloth);
    poly(x, [225,572, 294,572, 300,928, 231,928], cloth);
    /* shoes */
    ellipse(x, 172, 956, 54, 21, "#dedede");
    ellipse(x, 268, 956, 54, 21, "#dedede");
  }

  var FW = 440, FH = 1080, particles = [];

  /* The figure is sampled from a cut-out of Naitik's own rooftop photo
     (data:image/png;base64, — his seated silhouette with the background
     removed and the photo's brightness kept). If that file cannot load,
     the hand-drawn silhouette above is used as a fallback so the effect
     never disappears. */
  var maskImg = new Image();
  var maskReady = false;
  maskImg.onload = function(){ maskReady = true; sampleFigure(); };
  maskImg.src = "data:image/png;base64,";

  function finishSample(pts){
    /* thin out to a cap, keeping an even cloud */
    var MAX = W < 700 ? 5200 : 9200;
    if(pts.length > MAX){
      var keep = [];
      var ratio = pts.length / MAX;
      for(var i = 0; i < pts.length; i += ratio) keep.push(pts[Math.floor(i)]);
      pts = keep;
    }
    particles = pts.map(function(p){
      var r = Math.random();
      var col = p.b > .72 && r > .35 ? "196,238,240" : (r > .5 ? "62,198,200" : "94,164,172");
      return {
        x: p.x, y: p.y, b: p.b, col: col,
        size: .9 + Math.random() * 1.5 + p.b * .5,
        phase: Math.random() * Math.PI * 2,
        speed: .5 + Math.random() * .9,
        ox: 0, oy: 0, vx: 0, vy: 0
      };
    });
  }

  function sampleFigure(){
    var off = document.createElement("canvas");
    var ox, data;
    if(maskReady){
      off.width = maskImg.naturalWidth; off.height = maskImg.naturalHeight;
      ox = off.getContext("2d");
      ox.drawImage(maskImg, 0, 0);
      FW = off.width; FH = off.height;
    } else {
      off.width = FW; off.height = FH;
      ox = off.getContext("2d");
      drawFigure(ox);
    }
    data = ox.getImageData(0, 0, off.width, off.height).data;
    var pts = [], step = 3;
    for(var y = 0; y < off.height; y += step){
      for(var x = 0; x < off.width; x += step){
        var idx = (y * off.width + x) * 4;
        if(data[idx + 3] > 120){
          pts.push({ x: x + (Math.random() - .5) * 2.4, y: y + (Math.random() - .5) * 2.4, b: data[idx] / 255 });
        }
      }
    }
    finishSample(pts);
  }

  var mouseX = -9999, mouseY = -9999, swayX = 0;
  window.addEventListener("pointermove", function(e){
    mouseX = e.clientX; mouseY = e.clientY;
  }, { passive: true });
  window.addEventListener("pointerleave", function(){ mouseX = -9999; mouseY = -9999; });

  function resize(){
    W = window.innerWidth; H = window.innerHeight;
    canvas.width = W * DPR; canvas.height = H * DPR;
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    sampleFigure();
  }
  window.addEventListener("resize", resize);

  var pctEl = document.getElementById("pct");
  var barEl = document.getElementById("progress");

  function scrollProgress(){
    var max = document.documentElement.scrollHeight - H;
    return max > 0 ? Math.min(1, Math.max(0, window.scrollY / max)) : 0;
  }

  function drawPerson(t){
    ctx.clearRect(0, 0, W, H);
    var prog = scrollProgress();
    barEl.style.width = (prog * 100).toFixed(1) + "%";
    if(pctEl) pctEl.textContent = Math.round(prog * 100) + "%";

    /* figure size: wide enough to read, tall enough to travel through */
    var figW = Math.min(W * (W < 700 ? .86 : .44), 620);
    var scale = figW / FW;
    var figH = FH * scale;
    /* camera: travel the figure over the first 84% of the page */
    var camProg = Math.min(1, prog / .84);
    var camY = camProg * Math.max(0, figH - H * .82);
    var targetSway = mouseX < 0 ? 0 : (mouseX / W - .5) * 22;
    swayX += (targetSway - swayX) * .04;
    var baseX = (W - figW) / 2 + swayX;
    var baseY = H * .06;

    for(var i = 0; i < particles.length; i++){
      var p = particles[i];
      var breathe = reduceMotion ? 0 : Math.sin(t * .001 * p.speed + p.phase) * 1.6;
      var sx = baseX + p.x * scale + breathe + p.ox;
      var sy = baseY + p.y * scale - camY + breathe * .6 + p.oy;
      if(sy < -12 || sy > H + 12 || sx < -12 || sx > W + 12) continue;

      /* pointer repulsion with spring return */
      var dx = sx - mouseX, dy = sy - mouseY;
      var d2 = dx * dx + dy * dy;
      if(d2 < 8100 && d2 > .01){
        var d = Math.sqrt(d2), f = (90 - d) / 90 * 2.4;
        p.vx += (dx / d) * f; p.vy += (dy / d) * f;
      }
      p.vx += -p.ox * .045; p.vy += -p.oy * .045;
      p.vx *= .86; p.vy *= .86;
      p.ox += p.vx; p.oy += p.vy;

      var tw = reduceMotion ? 1 : .82 + .18 * Math.sin(t * .002 * p.speed + p.phase * 2);
      var a = (.22 + .78 * p.b) * tw;
      ctx.fillStyle = "rgba(" + p.col + "," + a.toFixed(3) + ")";
      var s = p.size * (figW < 400 ? .8 : 1);
      ctx.fillRect(sx, sy, s, s);
    }
  }

  /* ============ 3. PHOTO PARALLAX ============ */
  var cards = Array.prototype.slice.call(document.querySelectorAll(".ph"));
  function drawCards(){
    cards.forEach(function(card){
      var r = card.getBoundingClientRect();
      if(r.bottom < -200 || r.top > H + 200) return;
      var sp = parseFloat(card.getAttribute("data-sp") || "0.1");
      var off = (r.top + r.height / 2 - H / 2) * -sp;
      card.style.transform = "translateY(" + off.toFixed(1) + "px)";
      var img = card.querySelector("img");
      if(img){
        var px = parseFloat(img.getAttribute("data-px") || "0.05");
        var ioff = (r.top + r.height / 2 - H / 2) * px;
        img.style.transform = "scale(1.18) translateY(" + ioff.toFixed(1) + "px)";
      }
    });
  }

  /* ============ 4. FOOTER WAVE ============ */
  var wave = document.getElementById("wave");
  var wctx = wave.getContext("2d");
  var waveVisible = false, waveW = 0, waveH = 280;
  function sizeWave(){
    waveW = wave.clientWidth;
    wave.width = waveW * DPR; wave.height = waveH * DPR;
    wctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  }
  window.addEventListener("resize", sizeWave);
  new IntersectionObserver(function(es){
    es.forEach(function(e){ waveVisible = e.isIntersecting; });
  }, { threshold: 0.05 }).observe(wave);

  function drawWave(t){
    if(!waveVisible || !waveW) return;
    wctx.clearRect(0, 0, waveW, waveH);
    var mid = waveH * .52, cols = Math.floor(waveW / 7), rows = 15;
    for(var cx = 0; cx <= cols; cx++){
      var px = cx * 7;
      var env = Math.sin(Math.PI * px / waveW);
      var lift = Math.sin(px * .006 + t * .0009) * 26 + Math.cos(px * .0032 - t * .0006) * 18;
      for(var r = 0; r < rows; r++){
        var depth = r / (rows - 1);
        var py = mid + (depth - .5) * 150 + lift * (.35 + depth * .75);
        var a = env * (.12 + depth * .75);
        if(a <= .02) continue;
        wctx.fillStyle = "rgba(72,205,208," + a.toFixed(3) + ")";
        var s = .8 + depth * 1.5;
        wctx.fillRect(px, py, s, s);
      }
    }
  }

  /* ============ main loop ============ */
  resize();
  sizeWave();
  if(reduceMotion){
    drawPerson(0); drawCards();
    window.addEventListener("scroll", function(){ drawPerson(0); drawCards(); }, { passive: true });
  } else {
    (function loop(t){
      drawPerson(t || 0);
      drawCards();
      drawWave(t || 0);
      requestAnimationFrame(loop);
    })(0);
  }
})();